// Converts the browser-global data files of the legacy app/ into JSON for the Rust core.
//   node scripts/sync-data.mjs   (mise run sync-data)
// earth-metrics.js is generated by scripts/compute_earth_metrics.py; re-run this after regenerating it.
import fs from 'node:fs';
import vm from 'node:vm';
import path from 'node:path';

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const ctx = { window: {}, L: undefined };
ctx.window = ctx;
vm.createContext(ctx);
for (const f of ['earth-metrics.js', 'bodies.js', 'data/missions.js']) {
  vm.runInContext(fs.readFileSync(path.join(root, 'app/js', f), 'utf8'), ctx, { filename: f });
}
const out = (name, v) => {
  fs.writeFileSync(path.join(root, 'data', name), JSON.stringify(v, null, 1) + '\n');
  console.log(`data/${name}: ${Array.isArray(v) ? v.length + ' items' : Object.keys(v).length + ' keys'}`);
};
out('earth-metrics.json', ctx.EARTH_METRICS);
out('bodies.json', ctx.BODIES);
out('oxides.json', ctx.OXIDES);
out('missions.json', { landings: ctx.MISSIONS, presets: ctx.WALK_PRESETS });
